CREATE COLUMN TABLE "TEST_AP"."OAOB" ("AlertCode" INTEGER CS_INT NOT NULL , "SendDate" LONGDATE CS_LONGDATE, "SendTime" SMALLINT CS_INT, "WasSent" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT NOT NULL , PRIMARY KEY ("AlertCode", "UserSign")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OAOB_USER" ON "TEST_AP"."OAOB" ( "UserSign" ASC )